from config import DATA_DIR
from data_store import LocalDataStore
from fastapi import APIRouter, HTTPException, status

from .schema import FeedbackInput, SearchResponse, SearchResult

router = APIRouter()


@router.get("/ping")
async def ping():
    return {"message": "pong"}


@router.get(
    "/search",
    response_model=SearchResponse,
    responses={
        status.HTTP_503_SERVICE_UNAVAILABLE: {
            "description": "Location data has not been generated by the ETL pipeline yet."
        }
    },
)
def search():
    data_store = LocalDataStore(DATA_DIR)
    try:
        locations = data_store.read_output_locations()
    except FileNotFoundError:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="Location data is not available yet.",
        )
    output = [SearchResult.from_location(location) for location in locations]

    return SearchResponse(results=output)


